base='AAAAAAGAGCGCACCUUCAAAGACAUGGUUCAAUAGCACCGGAGCGAGGACGGAAAAAAGCGCGAAAGCGCCCGGCGCACAAAAAAAAAAAAAAAAAAAAA'
# search 50,73,6,79 and nearby 5,7,78,80
best=(99,None,None)
for p50 in 'ACGU':
  for p73 in 'ACGU':
    for p5 in 'ACGU':
      for p7 in 'ACGU':
        for p78 in 'ACGU':
          for p80 in 'ACGU':
            seq=list(base)
            seq[50]=p50;seq[73]=p73;seq[5]=p5;seq[7]=p7;seq[78]=p78;seq[80]=p80
            s=''.join(seq)
            fc=RNA.fold_compound(s)
            m,e=fc.mfe()
            d=RNA.bp_distance(m,t)
            if d<best[0]:
                best=(d,s,m)
                if d==0:
                    print('SOLVED',s)
print('best',best[0])
print(best[1])
print(best[2])
